 15→
 16→export interface ChatbotPlatformStackProps extends cdk.StackProps {
 17→	/** Full domain for the app, e.g. "chat.example.com" */
 18→	domainName?: string;
 19→	/** Root hosted zone name, e.g. "example.com" */
 20→	hostedZoneName?: string;
 21→	/** Route 53 hosted zone ID (from your domain registrar/existing zone) */
 22→	hostedZoneId?: string;
 23→	/** Email "From" address for verification/invite emails, e.g. "noreply@example.com" */
 24→	emailFromAddress?: string;
 25→	/** GitHub repo (owner/name) for OIDC federation, e.g. "ianshan0915/chatbot-platform" */
 26→	githubRepo?: string;
 27→}
 28→
 29→export class ChatbotPlatformStack extends cdk.Stack {
 30→	constructor(scope: Construct, id: string, props: ChatbotPlatformStackProps) {
 31→		super(scope, id, props);
 32→
 33→		// ----------------------------------------------------------------
 34→		// VPC — 2 AZs, public + private subnets (NAT gateway for outbound)
 35→		// ----------------------------------------------------------------
 36→		const vpc = new ec2.Vpc(this, "Vpc", {
 37→			maxAzs: 2,
 38→			natGateways: 1, // Keep costs low; 1 NAT is fine for non-HA start
 39→			subnetConfiguration: [
 40→				{ name: "Public", subnetType: ec2.SubnetType.PUBLIC, cidrMask: 24 },
 41→				{ name: "Private", subnetType: ec2.SubnetType.PRIVATE_WITH_EGRESS, cidrMask: 24 },
 42→			],
 43→		});
 44→
 45→		// ----------------------------------------------------------------
 46→		// S3 — file & skill storage
 47→		// ----------------------------------------------------------------
 48→		const storageBucket = new s3.Bucket(this, "StorageBucket", {
 49→			bucketName: cdk.PhysicalName.GENERATE_IF_NEEDED,
 50→			encryption: s3.BucketEncryption.S3_MANAGED,
 51→			blockPublicAccess: s3.BlockPublicAccess.BLOCK_ALL,
 52→			removalPolicy: cdk.RemovalPolicy.RETAIN, // Don't delete user files on stack destroy
 53→			versioned: true,
 54→			lifecycleRules: [
 55→				{
 56→					// Clean up incomplete multipart uploads
 57→					abortIncompleteMultipartUploadAfter: cdk.Duration.days(7),
 58→				},
 59→			],
 60→		});
 61→
 62→		// ----------------------------------------------------------------
 63→		// Secrets Manager — application secrets
 64→		// ----------------------------------------------------------------
 65→		const appSecrets = new secretsmanager.Secret(this, "AppSecrets", {
 66→			secretName: "chatbot-platform/app-secrets",
 67→			description: "Chatbot Platform application secrets (JWT_SECRET auto-generated)",
 68→			generateSecretString: {
 69→				secretStringTemplate: JSON.stringify({
 70→					JWT_SECRET: "",
 71→				}),
 72→				generateStringKey: "JWT_SECRET",
 73→				excludePunctuation: true,
 74→				passwordLength: 64,
 75→			},
 76→		});
 77→
 78→		// ENCRYPTION_ROOT_KEY needs to be a 64-char hex string (32 bytes).
 79→		// Generate it as a separate secret since CDK can only auto-generate one field.
 80→		const encryptionKeySecret = new secretsmanager.Secret(this, "EncryptionKey", {
 81→			secretName: "chatbot-platform/encryption-key",
 82→			description: "AES-256 envelope encryption root key (64 hex chars)",
 83→			generateSecretString: {
 84→				excludePunctuation: true,
 85→				excludeUppercase: true, // hex chars only: 0-9 a-f
 86→				excludeCharacters: "ghijklmnopqrstuvwxyz", // restrict to hex
 87→				passwordLength: 64,
 88→			},
 89→		});
 90→
 91→		// Brave Search API key — imported from pre-created secret
 92→		const braveSearchKey = secretsmanager.Secret.fromSecretNameV2(
 93→			this, "BraveSearchKey", "chatbot-platform/brave-search-key",
 94→		);
 95→
 96→		// Google OAuth credentials (Antigravity / Gemini Code Assist) — pre-created secret
 97→		// with keys: client_id, client_secret
 98→		const googleOAuthSecret = secretsmanager.Secret.fromSecretNameV2(
 99→			this, "GoogleOAuthSecret", "chatbot-platform/google-oauth",
100→		);
101→
102→		// ----------------------------------------------------------------
103→		// RDS PostgreSQL — free tier eligible
104→		// ----------------------------------------------------------------
105→		const dbCredentials = rds.Credentials.fromGeneratedSecret("chatbot", {
106→			secretName: "chatbot-platform/db-credentials",
107→		});
108→
109→		const dbSecurityGroup = new ec2.SecurityGroup(this, "DbSecurityGroup", {
110→			vpc,
111→			description: "Security group for RDS PostgreSQL",
112→			allowAllOutbound: false,
113→		});
114→
115→		const database = new rds.DatabaseInstance(this, "Database", {
116→			engine: rds.DatabaseInstanceEngine.postgres({
117→				version: rds.PostgresEngineVersion.VER_16,
118→			}),
119→			instanceType: ec2.InstanceType.of(ec2.InstanceClass.T4G, ec2.InstanceSize.MICRO),
120→			vpc,
121→			vpcSubnets: { subnetType: ec2.SubnetType.PRIVATE_WITH_EGRESS },
122→			securityGroups: [dbSecurityGroup],
123→			credentials: dbCredentials,
124→			databaseName: "chatbot_platform",
125→			allocatedStorage: 20,
126→			maxAllocatedStorage: 50,
127→			storageEncrypted: true,
128→			multiAz: false, // Single AZ for cost savings
129→			backupRetention: cdk.Duration.days(7),
130→			deletionProtection: false, // Set to true for production
131→			removalPolicy: cdk.RemovalPolicy.SNAPSHOT,
132→		});
133→
134→		// ----------------------------------------------------------------
135→		// ECR — container registry
136→		// ----------------------------------------------------------------
137→		const repository = new ecr.Repository(this, "AppRepository", {
138→			repositoryName: "chatbot-platform",
139→			removalPolicy: cdk.RemovalPolicy.RETAIN,
140→			lifecycleRules: [
141→				{
142→					description: "Keep last 10 images",
143→					maxImageCount: 10,
144→				},
145→			],
146→		});
147→
148→		// ----------------------------------------------------------------
149→		// ECS Cluster
150→		// ----------------------------------------------------------------
151→		const cluster = new ecs.Cluster(this, "Cluster", {
152→			vpc,
153→			containerInsights: true,
154→		});
155→
156→		// ----------------------------------------------------------------
157→		// Route 53 + ACM (conditional on domain config)
158→		// ----------------------------------------------------------------
159→		let hostedZone: route53.IHostedZone | undefined;
160→		let certificate: acm.ICertificate | undefined;
161→
162→		if (props.domainName && props.hostedZoneName && props.hostedZoneId) {
163→			// Use the EXISTING hosted zone from the domain registrar.
164→			// Do NOT create a new zone — that causes orphan zones and DNS mismatch
165→			// since the registrar NS records point to the original zone.
166→			hostedZone = route53.HostedZone.fromHostedZoneAttributes(this, "HostedZone", {
167→				hostedZoneId: props.hostedZoneId,
168→				zoneName: props.hostedZoneName,
169→			});
170→
171→			certificate = new acm.Certificate(this, "Certificate", {
172→				domainName: props.domainName,
173→				validation: acm.CertificateValidation.fromDns(hostedZone),
174→			});
175→		}
176→
177→		// ----------------------------------------------------------------
178→		// SES — email delivery (verification emails, invites, job results)
179→		// ----------------------------------------------------------------
180→		// SES email identity for the domain.
181→		// Using Identity.domain() instead of Identity.publicHostedZone() because we
182→		// reference an existing zone via fromHostedZoneAttributes (returns IHostedZone,
183→		// not IPublicHostedZone). DKIM DNS records must be added manually to the zone
184→		// after first deploy (check SES console for the 3 CNAME records).
185→		if (props.hostedZoneName) {
186→			new ses.EmailIdentity(this, "SesIdentity", {
187→				identity: ses.Identity.domain(props.hostedZoneName),
188→			});
189→		}
190→
191→		// IAM user for SES SMTP credentials.
192→		// After deploy: generate SMTP credentials in IAM console for this user,
193→		// then store them in Secrets Manager under chatbot-platform/smtp-credentials.
194→		const smtpUser = new iam.User(this, "SmtpUser", {
195→			userName: "chatbot-platform-smtp",
196→		});
197→		smtpUser.addToPolicy(new iam.PolicyStatement({
198→			effect: iam.Effect.ALLOW,
199→			actions: ["ses:SendRawEmail"],
200→			resources: ["*"],
201→		}));
202→
203→		const smtpSecrets = new secretsmanager.Secret(this, "SmtpSecrets", {
204→			secretName: "chatbot-platform/smtp-credentials",
205→			description: "SES SMTP credentials — update after generating in IAM console",
206→			generateSecretString: {
207→				secretStringTemplate: JSON.stringify({
208→					username: "REPLACE_WITH_SES_SMTP_USERNAME",
209→					password: "REPLACE_WITH_SES_SMTP_PASSWORD",
210→				}),
211→				generateStringKey: "_placeholder",
212→			},
213→		});
214→
215→		// ----------------------------------------------------------------
216→		// Fargate Task Definition
217→		// ----------------------------------------------------------------
218→		const taskDefinition = new ecs.FargateTaskDefinition(this, "TaskDef", {
219→			memoryLimitMiB: 4096,
220→			cpu: 2048, // 2 vCPU — needed for child pi processes
221→		});
222→
223→		// Grant S3 access to the task role
224→		storageBucket.grantReadWrite(taskDefinition.taskRole);
225→
226→		// Grant Secrets Manager read access
227→		appSecrets.grantRead(taskDefinition.taskRole);
228→		encryptionKeySecret.grantRead(taskDefinition.taskRole);
229→		braveSearchKey.grantRead(taskDefinition.taskRole);
230→		googleOAuthSecret.grantRead(taskDefinition.taskRole);
231→
232→		// Build DATABASE_URL from RDS secret
233→		const dbSecret = database.secret!;
234→
235→		const logGroup = new logs.LogGroup(this, "AppLogGroup", {
236→			logGroupName: "/ecs/chatbot-platform",
237→			retention: logs.RetentionDays.ONE_MONTH,
238→			removalPolicy: cdk.RemovalPolicy.RETAIN, // Keep logs for debugging failed deploys
239→		});
240→
241→		taskDefinition.addContainer("app", {
242→			// Initial deployment uses a placeholder; after first `docker push` to ECR,
243→			// update to: ecs.ContainerImage.fromEcrRepository(repository, "latest")
244→			image: ecs.ContainerImage.fromEcrRepository(repository, "latest"),
245→			logging: ecs.LogDrivers.awsLogs({
246→				logGroup,
247→				streamPrefix: "app",
248→			}),
249→			environment: {
250→				NODE_ENV: "production",
251→				PORT: "3001",
252→				STORAGE_BACKEND: "s3",
253→				S3_BUCKET_NAME: storageBucket.bucketName,
254→				AWS_REGION: this.region,
255→				PROCESS_POOL_MAX: "30",
256→				PROCESS_IDLE_TIMEOUT_MS: "600000",
257→				ALLOWED_ORIGINS: props.domainName ? `https://${props.domainName}` : "",
258→				// SES SMTP (region-specific endpoint)
259→				SMTP_HOST: `email-smtp.${this.region}.amazonaws.com`,
260→				SMTP_PORT: "587",
261→				SMTP_SECURE: "false",
262→				EMAIL_FROM_ADDRESS: props.emailFromAddress || (props.domainName ? `noreply@${props.hostedZoneName || props.domainName}` : ""),
263→				APP_URL: props.domainName ? `https://${props.domainName}` : "",
264→				REGISTRATION_MODE: "open",
265→			},
266→			secrets: {
267→				// Inject individual secret fields as env vars
268→				JWT_SECRET: ecs.Secret.fromSecretsManager(appSecrets, "JWT_SECRET"),
269→				ENCRYPTION_ROOT_KEY: ecs.Secret.fromSecretsManager(encryptionKeySecret),
270→				// RDS credentials — construct DATABASE_URL in the container
271→				DB_HOST: ecs.Secret.fromSecretsManager(dbSecret, "host"),
272→				DB_PORT: ecs.Secret.fromSecretsManager(dbSecret, "port"),
273→				DB_USERNAME: ecs.Secret.fromSecretsManager(dbSecret, "username"),
274→				DB_PASSWORD: ecs.Secret.fromSecretsManager(dbSecret, "password"),
275→				DB_NAME: ecs.Secret.fromSecretsManager(dbSecret, "dbname"),
276→				// SES SMTP credentials
277→				SMTP_USER: ecs.Secret.fromSecretsManager(smtpSecrets, "username"),
278→				SMTP_PASSWORD: ecs.Secret.fromSecretsManager(smtpSecrets, "password"),
279→				// Brave Search
280→				BRAVE_SEARCH_API_KEY: ecs.Secret.fromSecretsManager(braveSearchKey),
281→				// Google OAuth (Antigravity / Gemini Code Assist)
282→				OAUTH_GOOGLE_CLIENT_ID: ecs.Secret.fromSecretsManager(googleOAuthSecret, "client_id"),
283→				OAUTH_GOOGLE_CLIENT_SECRET: ecs.Secret.fromSecretsManager(googleOAuthSecret, "client_secret"),
284→			},
285→			portMappings: [{ containerPort: 3001, protocol: ecs.Protocol.TCP }],
286→			healthCheck: {
287→				command: ["CMD-SHELL", "curl -f http://localhost:3001/healthz || exit 1"],
288→				interval: cdk.Duration.seconds(30),
289→				timeout: cdk.Duration.seconds(5),
290→				retries: 3,
291→				startPeriod: cdk.Duration.seconds(60),
292→			},
293→		});
294→
295→		// ----------------------------------------------------------------
296→		// Fargate Service + ALB
297→		// ----------------------------------------------------------------
298→		const fargateService = new ecs_patterns.ApplicationLoadBalancedFargateService(
299→			this,
300→			"FargateService",
301→			{
302→				cluster,
303→				taskDefinition,
304→				desiredCount: 1,
305→				publicLoadBalancer: true,
306→				assignPublicIp: false, // Task in private subnet, outbound via NAT
307→				// Domain configuration (if provided)
308→				...(hostedZone && certificate && props.domainName
309→					? {
310→							domainName: props.domainName,
311→							domainZone: hostedZone,
312→							certificate,
313→							redirectHTTP: true,
314→						}
315→					: {}),
316→				// Health check configuration
