318→				circuitBreaker: { rollback: true }, // Auto-rollback on repeated task failures
319→			},
320→		);
321→
322→		// Configure ALB target group for WebSocket support
323→		fargateService.targetGroup.configureHealthCheck({
324→			path: "/healthz",
325→			healthyHttpCodes: "200",
326→			interval: cdk.Duration.seconds(30),
327→			timeout: cdk.Duration.seconds(5),
328→		});
329→
330→		// Enable stickiness for WebSocket connections
