357→		});
358→
359→		new cdk.CfnOutput(this, "StorageBucketName", {
360→			value: storageBucket.bucketName,
361→			description: "S3 bucket for file storage",
362→		});
363→
364→		new cdk.CfnOutput(this, "DatabaseEndpoint", {
