366→			description: "RDS PostgreSQL endpoint",
367→		});
368→
369→		new cdk.CfnOutput(this, "AppSecretsArn", {
370→			value: appSecrets.secretArn,
371→			description: "Secrets Manager ARN — update ENCRYPTION_ROOT_KEY after deploy",
372→		});
373→
374→		if (props.domainName) {
375→			new cdk.CfnOutput(this, "AppUrl", {
376→				value: `https://${props.domainName}`,
377→				description: "Application URL",
378→			});
379→		}
380→
381→		new cdk.CfnOutput(this, "SmtpUserName", {
382→			value: smtpUser.userName,
383→			description: "IAM user for SES SMTP — generate SMTP credentials in IAM console",
384→		});
385→
386→		new cdk.CfnOutput(this, "SmtpSecretsArn", {
387→			value: smtpSecrets.secretArn,
388→			description: "Secrets Manager ARN — store SES SMTP credentials here",
389→		});
390→
391→		new cdk.CfnOutput(this, "SmtpEndpoint", {
392→			value: `email-smtp.${this.region}.amazonaws.com:587`,
393→			description: "SES SMTP endpoint",
394→		});
395→
396→		// ----------------------------------------------------------------
397→		// GitHub Actions OIDC — keyless AWS auth for CI/CD
398→		// ----------------------------------------------------------------
399→		if (props.githubRepo) {
400→			const ghOidcProvider = new iam.OpenIdConnectProvider(this, "GitHubOidc", {
401→				url: "https://token.actions.githubusercontent.com",
402→				clientIds: ["sts.amazonaws.com"],
403→			});
404→
405→			const deployRole = new iam.Role(this, "GitHubActionsRole", {
406→				roleName: "chatbot-platform-github-actions",
407→				assumedBy: new iam.WebIdentityPrincipal(
408→					ghOidcProvider.openIdConnectProviderArn,
409→					{
410→						StringLike: {
411→							"token.actions.githubusercontent.com:sub": `repo:${props.githubRepo}:*`,
412→						},
413→						StringEquals: {
414→							"token.actions.githubusercontent.com:aud": "sts.amazonaws.com",
415→						},
416→					},
417→				),
418→				managedPolicies: [
419→					iam.ManagedPolicy.fromAwsManagedPolicyName("AdministratorAccess"),
420→				],
421→			});
422→
423→			new cdk.CfnOutput(this, "GitHubActionsRoleArn", {
424→				value: deployRole.roleArn,
425→				description: "IAM role ARN for GitHub Actions — set as AWS_DEPLOY_ROLE_ARN secret",
426→			});
427→		}
428→	}
