162→		if (props.domainName && props.hostedZoneName && props.hostedZoneId) {
163→			// Use the EXISTING hosted zone from the domain registrar.
164→			// Do NOT create a new zone — that causes orphan zones and DNS mismatch
165→			// since the registrar NS records point to the original zone.
166→			hostedZone = route53.HostedZone.fromHostedZoneAttributes(this, "HostedZone", {
