196→		});
197→		smtpUser.addToPolicy(new iam.PolicyStatement({
198→			effect: iam.Effect.ALLOW,
199→			actions: ["ses:SendRawEmail"],
200→			resources: ["*"],
201→		}));
202→
203→		const smtpSecrets = new secretsmanager.Secret(this, "SmtpSecrets", {
204→			secretName: "chatbot-platform/smtp-credentials",
205→			description: "SES SMTP credentials — update after generating in IAM console",
206→			generateSecretString: {
207→				secretStringTemplate: JSON.stringify({
208→					username: "REPLACE_WITH_SES_SMTP_USERNAME",
209→					password: "REPLACE_WITH_SES_SMTP_PASSWORD",
210→				}),
211→				generateStringKey: "_placeholder",
212→			},
213→		});
214→
215→		// ----------------------------------------------------------------
216→		// Fargate Task Definition
217→		// ----------------------------------------------------------------
218→		const taskDefinition = new ecs.FargateTaskDefinition(this, "TaskDef", {
219→			memoryLimitMiB: 4096,
220→			cpu: 2048, // 2 vCPU — needed for child pi processes
221→		});
222→
223→		// Grant S3 access to the task role
