234→
235→		const logGroup = new logs.LogGroup(this, "AppLogGroup", {
236→			logGroupName: "/ecs/chatbot-platform",
237→			retention: logs.RetentionDays.ONE_MONTH,
238→			removalPolicy: cdk.RemovalPolicy.RETAIN, // Keep logs for debugging failed deploys
239→		});
