261→				SMTP_SECURE: "false",
262→				EMAIL_FROM_ADDRESS: props.emailFromAddress || (props.domainName ? `noreply@${props.hostedZoneName || props.domainName}` : ""),
263→				APP_URL: props.domainName ? `https://${props.domainName}` : "",
264→				REGISTRATION_MODE: "open",
265→			},
