		fargateService.loadBalancer.setAttribute("idle_timeout.timeout_seconds", "3600");

		// Allow Fargate tasks to connect to RDS
		dbSecurityGroup.addIngressRule(
			fargateService.service.connections.securityGroups[0],
			ec2.Port.tcp(5432),
